// Credit: the OpenRGB project, https://gitlab.com/CalcProgrammer1/OpenRGB (GPL-2.0-or-later).
// USB devices OpenRGB can control, as vendor<<16|product, sorted, each with the name of the
// OpenRGB controller (= lighting protocol) that drives it.
// Generated by tools/gen_openrgb_ids.py from OpenRGB's 60-openrgb.rules (master, 1.1.50 git fc3aa07, 2026-11-04).
// Used only to tell the user what a detected RGB device is; nothing here talks to hardware.

/// The OpenRGB controller name for a USB device, if OpenRGB knows it.
pub fn protocol(vid: u16, pid: u16) -> Option<&'static str> {
    let key = ((vid as u32) << 16) | pid as u32;
    OPENRGB_USB.binary_search_by_key(&key, |e| e.0).ok().map(|i| NAMES[OPENRGB_USB[i].1 as usize])
}

